+    data->state.provider;
@@
-  data->state.baseprov = OSSL_PROVIDER_try_load(data->state.libctx, "base", 1);
+  data->state.baseprov = OSSL_PROVIDER_try_load(data->state.libctx, "base", 1);
+  ((struct ossl_libctx_anchor *)data->state.libctx_anchor)->baseprov =
+    data->state.baseprov;
@@
 static void ossl_close(struct Curl_cfilter *cf, struct Curl_easy *data)
 {
@@
   if(octx->ssl_ctx) {
     SSL_CTX_free(octx->ssl_ctx);
     octx->ssl_ctx = NULL;
     octx->x509_store_setup = FALSE;
   }
+  /* libctx must outlive SSL_CTX_free(); release only after it */
+  Curl_ossl_libctx_anchor_release(octx->libctx_anchor);
+  octx->libctx_anchor = NULL;
   if(octx->bio_method) {
@@
   octx->ssl_ctx =
 #ifdef OPENSSL_HAS_PROVIDERS
     data->state.libctx ?
     SSL_CTX_new_ex(data->state.libctx, data->state.propq, req_method):
 #endif
     SSL_CTX_new(req_method);
@@
 #ifdef OPENSSL_HAS_PROVIDERS
   if(data->state.libctx) {
+    struct ossl_libctx_anchor *anchor = data->state.libctx_anchor;
+    /* This SSL_CTX borrowed anchor->libctx without an OpenSSL ref.
+     * Hold one curl ref until ossl_close() has destroyed the SSL_CTX.
+     * connclose() only blocks pool reuse; cshutdn can outlive *data. */
+    DEBUGASSERT(anchor);
+    anchor->refcount++;
+    octx->libctx_anchor = anchor;
     connclose(data->conn);
+  }
 #endif

diff --git a/lib/vquic/vquic-tls.c b/lib/vquic/vquic-tls.c
--- a/lib/vquic/vquic-tls.c
+++ b/lib/vquic/vquic-tls.c
@@
   if(ctx->ossl.ssl)
     SSL_free(ctx->ossl.ssl);
   if(ctx->ossl.ssl_ctx)
     SSL_CTX_free(ctx->ossl.ssl_ctx);
+  Curl_ossl_libctx_anchor_release(ctx->ossl.libctx_anchor);
+  ctx->ossl.libctx_anchor = NULL;
 #endif
```

`anchor->refcount++` and the matching decrement need to be atomic (`atomic_fetch_add` / `atomic_fetch_sub`, or the equivalent already used in-tree). If `SSL_CTX_new_ex()` fails, do not take the extra reference. Any error path that destroys an `ossl_ctx` without `ossl_close()` has to release `libctx_anchor` the same way `Curl_vquic_tls_cleanup()` does, and only after `SSL_CTX_free()`.

